@startuml

class Employee {
  + id : string
  + name : string
  + address : string
}

class AssemblyService {
  + kms : int
  + workHours : float
  + admissionDate : date
  + finishDate : date
}

class PartAccessory {
  + category : string
  + serialNumber : string
  + price : double
}

class Car {
  + licensePlate : string
  + make : string
  + model : string
  + color : string
}

class Owner {
  + id : string
  + name : string
  + address : string
  + phone : string
}

Employee "1" -- "*" AssemblyService : responsible for
AssemblyService "*" -- "1" Car : executed in
AssemblyService "*" -- "*" PartAccessory : fits
PartAccessory "*" -- "*" Car : fits in
Car "1" -- "*" AssemblyService : undergoes
Owner "1" -- "*" Car : owns

@enduml

